type FeatureWithMarkerSymbol = {
  properties?: {
    style?: {
      color?: string;
      opacity?: number;
      markerSize?: number;
      weight?: number;
      markerFilled?: boolean;
      markerRotation?: number;
      renderScale?: number;
    };
    symbol?: unknown;
  };
};

type MarkerSymbolHtmlOptions = {
  size?: number;
};

type DrawMarkerSymbolOptions = {
  strokeColor?: string;
  shadow?: boolean;
};

type LeafletMarkerIcon = DivIcon | Icon<IconOptions>;

type LeafletLike = {
  divIcon: (options: {
    className?: string;
    iconSize?: [number, number];
    iconAnchor?: [number, number];
    html?: string;
  }) => LeafletMarkerIcon;
};

export type DroMapMarkerSymbolCategoryId =
  | "basic"
  | "settlement"
  | "transport"
  | "economy"
  | "energy"
  | "environment"
  | "geopolitics"
  | "history"
  | "military"
  | "society"
  | "risk";

export type DroMapMarkerSymbolCategory = {
  id: DroMapMarkerSymbolCategoryId;
  label: string;
};

export type DroMapMarkerSymbolOption = {
  id: DroMapMarkerBuiltinSymbol;
  label: string;
  categoryId: DroMapMarkerSymbolCategoryId;
  keywords: string[];
  sourceIcon: string;
};

type TablerNode =
  | { tag: "path"; d: string }
  | { tag: "line"; x1: number; y1: number; x2: number; y2: number }
  | { tag: "polyline" | "polygon"; points: string }
  | { tag: "circle"; cx: number; cy: number; r: number }
  | {
      tag: "rect";
      x: number;
      y: number;
      width: number;
      height: number;
      rx?: number;
      ry?: number;
    }
  | { tag: "ellipse"; cx: number; cy: number; rx: number; ry: number };

type MarkerDefinition = DroMapMarkerSymbolOption & {
  nodes: TablerNode[];
};

function tabler(
  id: string,
  label: string,
  categoryId: DroMapMarkerSymbolCategoryId,
  sourceIcon: string,
  nodes: TablerNode[],
  keywords: string[] = [],
): MarkerDefinition {
  return { id, label, categoryId, sourceIcon, nodes, keywords };
}

